const enemies=[];let kills=0,souls=0,hp=100,started=false,ended=false,attackTimer=0,dashTimer=0,damageTimer=0,spawnTimer=0,time=0;const keys={};
function makeEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const body=box(g,new THREE.CapsuleGeometry(.4,.68,4,8),shadeMat,[0,.78,0]);const head2=box(g,new THREE.IcosahedronGeometry(.34,1),shadeMat,[0,1.52,0]);const eye1=box(g,new THREE.SphereGeometry(.055,8,6),flame,[-.12,1.57,-.27]);const eye2=box(g,new THREE.SphereGeometry(.055,8,6),flame,[.12,1.57,-.27]);for(let k=0;k<3;k++)box(g,new THREE.ConeGeometry(.14,.55,5),shadeMat,[(k-1)*.25,2.1,-.05],[0,0,(k-1)*-.25]);const aura=new THREE.Mesh(new THREE.TorusGeometry(.48,.025,5,20),flame);aura.rotation.x=Math.PI/2;aura.position.y=.12;g.add(aura);g.userData={hp:2,hit:0,phase:Math.random()*5,speed:1.15+Math.random()*.32};enemies.push(g);return g}
function spawnEnemy(){const a=Math.random()*Math.PI*2,r=14+Math.random()*3;makeEnemy(Math.sin(a)*r,Math.cos(a)*r)}for(let i=0;i<5;i++)spawnEnemy();
const slash=new THREE.Mesh(new THREE.TorusGeometry(1.2,.09,6,36,Math.PI*1.35),new THREE.MeshBasicMaterial({color:'#a9eaff',transparent:true,opacity:.85}));slash.rotation.x=Math.PI/2;slash.visible=false;scene.add(slash);
const particles=[];function burst(pos,color='#91e7ff',count=10){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.06+Math.random()*.07,0),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);particles.push({mesh:m,v:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:.65+Math.random()*.45})}}
function notify(txt){const el=document.querySelector('#toast');el.textContent=txt;el.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>el.classList.remove('show'),1600)}
function updateHUD(){document.querySelector('#souls').textContent=souls;document.querySelector('#kills').textContent=kills;document.querySelector('#health').style.width=hp+'%';document.querySelector('#objectiveTitle').textContent=souls===3&&kills>=8?'THE WAY HOME IS OPEN':'THE SHATTERED CHOIR';document.querySelector('#objectiveText').textContent=souls===3&&kills>=8?'The gate is awake. Reach the luminous arch to escape the fallen realm.':`Recover ${3-souls} soul-shard${3-souls===1?'':'s'} and cleanse ${8-kills} more wraith${8-kills===1?'':'s'}.`}
function doAttack(){if(!started||ended||attackTimer>0)return;attackTimer=.58;slash.visible=true;slash.position.set(hero.position.x,1.15,hero.position.z-1.0);slash.rotation.z=-hero.rotation.y;for(const e of [...enemies]){const d=e.position.distanceTo(hero.position);if(d<3.35){e.userData.hp--;e.userData.hit=.2;burst(e.position.clone().add(new THREE.Vector3(0,1,0)),'#afeaff',6);if(e.userData.hp<=0){burst(e.position.clone().add(new THREE.Vector3(0,1,0)),'#de9b6b',16);scene.remove(e);enemies.splice(enemies.indexOf(e),1);kills++;spawnTimer=1.6;updateHUD()}}}}
function doDash(){if(!started||ended||dashTimer>0)return;dashTimer=.9;damageTimer=.35;hero.userData.dash=.22;}
let joy={x:0,y:0};const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');let stickPointer=null;function setJoy(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=39,m=Math.min(len,max);joy.x=len?dx/len*m/max:0;joy.y=len?dy/len*m/max:0;nub.style.transform=`translate(${joy.x*m}px,${joy.y*m}px)`}stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);setJoy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)setJoy(e)});const resetJoy=()=>{stickPointer=null;joy={x:0,y:0};nub.style.transform=''};stick.addEventListener('pointerup',resetJoy);stick.addEventListener('pointercancel',resetJoy);
document.querySelector('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();doAttack()});document.querySelector('#dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();doDash()});
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'||e.code==='KeyJ')doAttack();if(e.code==='ShiftLeft'||e.code==='ShiftRight'||e.code==='KeyK')doDash()});addEventListener('keyup',e=>keys[e.code]=false);
document.querySelector('#start').addEventListener('click',()=>{started=true;document.querySelector('#overlay').classList.add('hidden');document.querySelector('#hint').textContent=matchMedia('(pointer:coarse)').matches?'LEFT STICK MOVE · STRIKE ATTACK · DASH EVADE':'WASD / ARROWS MOVE · SPACE ATTACK · SHIFT DASH'});
function finish(win){ended=true;const card=document.querySelector('.card');card.innerHTML=`<div class="eyebrow">${win?'THE VEIL HAS LIFTED':'THE SANCTUARY CLAIMS ANOTHER'}</div><h1>${win?'ASCENSION':'FALLEN'}<span>${win?'BARAKEL IS FREE':'YOUR LIGHT FADES'}</span></h1><p>${win?'The shards ring as one. Your wings remember the sky. The fallen angel has found his way home.':'The shadows overwhelm the exiled one. But no fall is forever.'}</p><button class="start" id="again">${win?'PLAY AGAIN':'RISE AGAIN'}</button>`;document.querySelector('#overlay').classList.remove('hidden');document.querySelector('#again').onclick=()=>location.reload()}
function update(dt){time+=dt;attackTimer=Math.max(0,attackTimer-dt);dashTimer=Math.max(0,dashTimer-dt);damageTimer=Math.max(0,damageTimer-dt);spawnTimer=Math.max(0,spawnTimer-dt);if(attackTimer<=0)slash.visible=false;
// floating accents
for(const c of gate.children){if(c.userData.float!==undefined){c.position.y=2+Math.sin(time*1.8+c.userData.float)*.6;c.rotation.y+=dt*.5}}portal.rotation.z=Math.sin(time*.7)*.15;portalCore.material.opacity=.25+Math.sin(time*2)*.08;warm.intensity=42+Math.sin(time*4)*4;
for(const o of scene.children)if(o.userData.flicker)o.scale.y=.8+Math.random()*.5;
if(!started||ended)return;
let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x,mz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+joy.y;const len=Math.hypot(mx,mz);if(len>1){mx/=len;mz/=len}const moving=Math.hypot(mx,mz)>.08;if(moving){const sp=keys.ShiftLeft||keys.ShiftRight?9:5.7;hero.position.x+=mx*sp*dt;hero.position.z+=mz*sp*dt;hero.rotation.y=Math.atan2(mx,mz);leftWing.rotation.z=Math.sin(time*10)*.09;rightWing.rotation.z=-Math.sin(time*10)*.09} else{leftWing.rotation.z=Math.sin(time*2)*.025;rightWing.rotation.z=-Math.sin(time*2)*.025}
if(hero.userData.dash>0){hero.userData.dash-=dt;hero.position.x+=Math.sin(hero.rotation.y)*13*dt;hero.position.z+=Math.cos(hero.rotation.y)*13*dt;hero.scale.set(1.1,.9,1.1)}else hero.scale.setScalar(1);
const rr=Math.hypot(hero.position.x,hero.position.z);if(rr>20.2){hero.position.x*=20.2/rr;hero.position.z*=20.2/rr}
for(const p of pickups){if(p.userData.taken)continue;p.rotation.y+=dt*.65;p.position.y=Math.sin(time*2+p.position.x)*.18;if(p.position.distanceTo(hero.position)<1.65){p.userData.taken=true;scene.remove(p);souls++;burst(new THREE.Vector3(p.position.x,1,p.position.z),'#a6efff',22);notify('SOUL-SHARD RECOVERED');updateHUD()}}
for(const e of [...enemies]){e.userData.phase+=dt*3;e.position.y=Math.abs(Math.sin(e.userData.phase))*.12;e.rotation.y+=dt*.45;const dx=hero.position.x-e.position.x,dz=hero.position.z-e.position.z,d=Math.hypot(dx,dz);if(d>1.5){e.position.x+=dx/d*e.userData.speed*dt;e.position.z+=dz/d*e.userData.speed*dt;e.rotation.y=Math.atan2(dx,dz)}else if(damageTimer<=0){hp=Math.max(0,hp-12);damageTimer=.85;hero.material&& (hero.material.opacity=.5);updateHUD();if(hp<=0)finish(false)}if(e.userData.hit>0){e.userData.hit-=dt;e.position.x-=dx/(d||1)*dt*3}}
if(enemies.length<5&&kills<8&&spawnTimer===0)spawnEnemy();if(souls===3&&kills>=8&&Math.hypot(hero.position.x,hero.position.z+18)<4.4)finish(true);
const target=new THREE.Vector3(hero.position.x,1.15,hero.position.z+6.8);camera.position.lerp(new THREE.Vector3(hero.position.x,5.9,hero.position.z+10.5),1-Math.pow(.001,dt));camera.lookAt(target);
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=4*dt;p.mesh.material.opacity=Math.max(0,p.life);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}}
function render(){renderer.render(scene,camera)}let prev=performance.now();function loop(now){requestAnimationFrame(loop);const dt=Math.min((now-prev)/1000,.04);prev=now;update(dt);render()}requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});updateHUD();
</script>
</body>
</html>

