content.text:
.hud-top,.vitals,.quest,.map-panel,.target,.interaction,.touch-ui,.message,.toast{position:absolute;z-index:2}
.target{top:48%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:8px;padding:7px 12px;background:#172016bd;border:1px solid #e4d1a06b;opacity:0;transition:opacity .2s;pointer-events:none}
.target.visible{opacity:1}
.target>span{font-size:20px;color:var(--gold)}
.target b,.target small{display:block;font:9px 'Cinzel',serif;letter-spacing:.1em}
.target small{font-size:7px;color:#c2b79c;margin-top:3px}
.interaction{left:50%;bottom:27%;transform:translateX(-50%);display:none;align-items:center;gap:6px;padding:7px 12px;border:1px solid #e5ce94a8;background:#171b16d9;color:#f4e3bf;box-shadow:0 2px 10px #0008;font:10px 'Cinzel',serif;letter-spacing:.12em}
.interaction span{color:var(--gold);font-size:16px}
.interaction small{font:7px 'DM Sans',sans-serif;color:#c9b991;margin-left:4px}
.toast{left:50%;top:27%;transform:translate(-50%,-8px);padding:8px 14px;background:#1a2119e8;border:1px solid #d8b87888;font:10px 'Cinzel',serif;letter-spacing:.12em;opacity:0;transition:.2s;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.overlay,.dialog,.inventory,.pause{position:absolute;inset:0;z-index:5;display:grid;place-items:center;padding:20px;background:rgba(9,12,9,.72);backdrop-filter:blur(5px);transition:opacity .3s}
.overlay.hidden,.dialog.hidden,.inventory.hidden,.pause.hidden{opacity:0;pointer-events:none}
.intro-copy>small,.pause-card>small{font:9px 'Cinzel',serif;letter-spacing:.2em;color:var(--gold)}
.intro-copy button,.continue,.pause-card button{border:1px solid #dec68d;background:linear-gradient(110deg,#74603b,#453d2a);padding:13px 17px;font:10px 'Cinzel',serif;letter-spacing:.13em;color:#fff2d6}
.dialog{z-index:6;background:rgba(4,7,5,.24);backdrop-filter:none;align-items:end;padding-bottom:max(155px,env(safe-area-inset-bottom))}
.dialog-card{width:min(520px,92vw);padding:16px 19px;background:linear-gradient(110deg,#20251d,#151914);border:1px solid #d6bb797c;box-shadow:0 8px 28px #000b}
.dialog-top{display:flex;justify-content:space-between;align-items:center;color:var(--gold);font:10px 'Cinzel',serif;letter-spacing:.16em}
.dialog-top button,.inventory-card>button{border:0;background:none;color:#eee0c2;font-size:23px}
.dialog-card p{font-size:13px;line-height:1.65;color:#eee6d4;margin:13px 0}
.dialog-card:after{content:'';display:block;clear:both}
.inventory{z-index:6}
.inventory-card,.pause-card{width:min(400px,92vw);padding:25px;background:#1b2019;border:1px solid #d6bb797a;box-shadow:0 15px 45px #000b;position:relative}
.inventory-card>button{position:absolute;right:14px;top:9px}
.inventory-card>small{font:9px 'Cinzel',serif;letter-spacing:.2em;color:var(--gold)}
.inventory-card h2,.pause-card h2{font:500 27px 'Cinzel',serif;margin:6px 0 20px}
.inventory-card>p{font-size:11px;color:#c4beae;margin-bottom:0}
.pause{z-index:6}
.pause-card{text-align:center}
.pause-card h2{margin-bottom:20px}
.pause-card button{display:block;width:100%;margin:8px 0;background:#292d24;border-color:#92815a}
.pause-card button:first-of-type{background:#655637}
.interaction{bottom:171px}
.dialog{padding-bottom:160px}
.dialog{padding-bottom:123px}
.dialog-card{padding:11px 15px}
.dialog-card p{margin:8px 0;font-size:12px}

